package com.ebuddy.domain;
import jakarta.persistence.*; import java.io.Serializable; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="contact_list") public class ContactEntity { @EmbeddedId ContactId id; @Enumerated(EnumType.STRING) @Column(nullable=false) ContactState state=ContactState.pending; @Column(length=80) String alias; @Column(name="created_at",nullable=false) Instant createdAt=Instant.now(); @Column(name="updated_at",nullable=false) Instant updatedAt=Instant.now(); protected ContactEntity(){} public ContactEntity(UUID a,UUID b){id=new ContactId(a,b);} public UUID owner(){return id.ownerUserId;} public UUID contact(){return id.contactUserId;} public ContactState getState(){return state;} public String getAlias(){return alias;} public void setState(ContactState s){state=s;} public void setAlias(String a){alias=a;} }
@Embeddable class ContactId implements Serializable { @Column(name="owner_user_id") UUID ownerUserId; @Column(name="contact_user_id") UUID contactUserId; protected ContactId(){} ContactId(UUID a,UUID b){ownerUserId=a;contactUserId=b;} public boolean equals(Object o){return o instanceof ContactId x&&ownerUserId.equals(x.ownerUserId)&&contactUserId.equals(x.contactUserId);} public int hashCode(){return java.util.Objects.hash(ownerUserId,contactUserId);} }
